_ED_P = 2 ** 255 - 19
_ED_Q = 2 ** 252 + 27742317777372353535851937790883648493
_ED_D = -121665 * pow(121666, _ED_P - 2, _ED_P) % _ED_P
_ED_I = pow(2, (_ED_P - 1) // 4, _ED_P)
def _ed_add(a, b):
    (x1, y1), (x2, y2) = a, b
    t = _ED_D * x1 * x2 * y1 * y2 % _ED_P
    return ((x1 * y2 + x2 * y1) * pow(1 + t, _ED_P - 2, _ED_P) % _ED_P,
            (y1 * y2 + x1 * x2) * pow(1 - t, _ED_P - 2, _ED_P) % _ED_P)
def _ed_mul(pt, e):
    r, q = (0, 1), pt
    while e:
        if e & 1: r = _ed_add(r, q)
        q = _ed_add(q, q); e >>= 1
    return r
def _ed_point(b32):
    y = int.from_bytes(b32, "little"); sign, y = y >> 255, y & ((1 << 255) - 1)
    if y >= _ED_P: return None
    xx = (y * y - 1) * pow(_ED_D * y * y + 1, _ED_P - 2, _ED_P) % _ED_P
    x = pow(xx, (_ED_P + 3) // 8, _ED_P)
    if (x * x - xx) % _ED_P: x = x * _ED_I % _ED_P
    if (x * x - xx) % _ED_P: return None
    if x & 1 != sign: x = _ED_P - x
    return (x, y)
